sys_script_include.script:
var fetchdetailsfromeventrecordtable = Class.create();
fetchdetailsfromeventrecordtable.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    fetchEventDetails: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790233_event_ma_event_record');
        gr.addQuery('sys_id', eventId);
        gr.query();

        if (gr.next()) {
            var res = {
                taskName: gr.getValue('event_name'),
                location: gr.getValue('location'),
                email: gr.getValue('email'),
				isVIP:gr.getValue('u_is_vip')
            };
            return JSON.stringify(res);
        } else {
            return JSON.stringify({
                error: 'No data found'
            });
        }
    },

    type: 'fetchdetailsfromeventrecordtable'
});
